1	import i18n from "@/i18n/i18n";
2	
3	type DateInput = Date | string | null | undefined;
4	
5	type FormatDateOptions = Intl.DateTimeFormatOptions & {
6	  language?: string;
7	};
8	
9	const DATE_ONLY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
10	const YEAR_MONTH_RE = /^(\d{4})-(\d{2})$/;
11	const YEAR_RE = /^(\d{4})$/;
12	
13	const LANGUAGE_LOCALES: Record<string, string> = {
14	  de: "de-DE",
15	  en: "en-US",
16	};
17	
18	export type DatePrecision = "day" | "month" | "year" | null;
19	
20	export function getDatePrecision(value: string | null | undefined): DatePrecision {
21	  if (!value) return null;
22	  if (DATE_ONLY_RE.test(value)) return "day";
23	  if (YEAR_MONTH_RE.test(value)) return "month";
24	  if (YEAR_RE.test(value)) return "year";
25	  return null;
26	}
27	
28	export function isValidPartialDate(value: string): boolean {
29	  const precision = getDatePrecision(value);
30	  if (precision === null) return false;
31	
32	  const parts = value.split("-");
33	  const year = Number(parts[0]);
34	
35	  if (precision === "month" || precision === "day") {
36	    const month = Number(parts[1]);
37	    if (month < 1 || month > 12) return false;
38	
39	    if (precision === "day") {
40	      const day = Number(parts[2]);
41	      const daysInMonth = new Date(year, month, 0).getDate();
42	      if (day < 1 || day > daysInMonth) return false;
43	    }
44	  }
45	
46	  return true;
47	}
48	
49	/** Compare two partial date strings. Returns negative, zero, or positive. */
50	export function comparePartialDates(a: string | null, b: string | null): number {
51	  if (!a && !b) return 0;
52	  if (!a) return -1;
53	  if (!b) return 1;
54	  // Lexicographic on the common prefix works for YYYY, YYYY-MM, YYYY-MM-DD.
55	  return a.localeCompare(b);
56	}
57	
58	/** Extract the 4-digit year from a partial date string without using `new Date`. */
59	export function getYear(value: string | null | undefined): number | null {
60	  if (!value) return null;
61	  const m = value.match(/^(\d{4})/);
62	  return m ? Number(m[1]) : null;
63	}
64	
65	type DateField = "day" | "month" | "year";
66	
67	/** Order in which day / month / year appear for the given locale. */
68	function getLocaleDateOrder(locale: string): DateField[] {
69	  const parts = new Intl.DateTimeFormat(locale, {
70	    day: "2-digit",
71	    month: "2-digit",
72	    year: "numeric",
73	  }).formatToParts(new Date(2000, 0, 2));
74	  const order: DateField[] = [];
75	  for (const part of parts) {
76	    if (part.type === "day") order.push("day");
77	    else if (part.type === "month") order.push("month");
78	    else if (part.type === "year") order.push("year");
79	  }
80	  return order.length === 3 ? order : ["day", "month", "year"];
81	}
82	
83	/** Separator a locale uses between date fields (e.g. "." for de, "/" for en). */
84	function getLocaleDateSeparator(locale: string): string {
85	  const parts = new Intl.DateTimeFormat(locale, {
86	    day: "2-digit",
87	    month: "2-digit",
88	    year: "numeric",
89	  }).formatToParts(new Date(2000, 0, 2));
90	  const literal = parts.find((p) => p.type === "literal");
91	  const trimmed = literal?.value.trim();
92	  return trimmed && trimmed.length > 0 ? trimmed[0] : ".";
93	}
94	
95	/**
96	 * Render a partial date as a numeric, re-typeable string in the locale's field
97	 * order (e.g. "23.06.2026" for de, "06/23/2026" for en, "2026" for year-only).
98	 * Unlike {@link formatDate} this never uses long month names, so the result can
99	 * be fed straight back into {@link parsePartialDateInput}.
100	 */
101	export function formatPartialDateForInput(
102	  value: string | null | undefined,
103	  language?: string,
104	): string {
105	  const precision = getDatePrecision(value);
106	  if (!value || !precision) return "";
107	
108	  const [year, month, day] = value.split("-");
109	  if (precision === "year") return year;
110	
111	  const locale = resolveDateLocale(language);
112	  const separator = getLocaleDateSeparator(locale);
113	  const fieldValues: Record<DateField, string | undefined> = {
114	    year,
115	    month,
116	    day: precision === "day" ? day : undefined,
117	  };
118	  return getLocaleDateOrder(locale)
119	    .map((field) => fieldValues[field])
120	    .filter((part): part is string => part !== undefined)
121	    .join(separator);
122	}
123	
124	/**
125	 * Parse a user-typed date into the internal partial-date format
126	 * (`YYYY`, `YYYY-MM`, or `YYYY-MM-DD`). Accepts `.`, `/`, `-` or whitespace as
127	 * separators, ISO order (year first) as well as the locale's field order, and
128	 * partial precision (year only, or month + year). The year must be four digits.
129	 *
130	 * Returns `{ value: null, valid: true }` for empty input (a deliberate clear)
131	 * and `{ value: null, valid: false }` for anything unparseable.
132	 */
133	export function parsePartialDateInput(
134	  text: string,
135	  language?: string,
136	): { value: string | null; valid: boolean } {
137	  const trimmed = text.trim();
138	  if (!trimmed) return { value: null, valid: true };
139	
140	  const invalid = { value: null, valid: false } as const;
141	
142	  const tokens = trimmed.split(/[\s./-]+/).filter(Boolean);
143	  if (tokens.length === 0 || tokens.length > 3) return invalid;
144	  if (!tokens.every((token) => /^\d+$/.test(token))) return invalid;
145	
146	  let year: number | null = null;
147	  let month: number | null = null;
148	  let day: number | null = null;
149	
150	  if (tokens.length === 1) {
151	    if (tokens[0].length !== 4) return invalid;
152	    year = Number(tokens[0]);
153	  } else if (tokens[0].length === 4) {
154	    // ISO-style: year first.
155	    year = Number(tokens[0]);
156	    month = Number(tokens[1]);
157	    if (tokens[2] !== undefined) day = Number(tokens[2]);
158	  } else {
159	    // Locale field order; the four-digit token is the year.
160	    const yearIndex = tokens.findIndex((token) => token.length === 4);
161	    if (yearIndex === -1) return invalid;
162	    year = Number(tokens[yearIndex]);
163	    const rest = tokens.filter((_, i) => i !== yearIndex);
164	    if (rest.length === 1) {
165	      // A single non-year token is always the month (e.g. "06.2026").
166	      month = Number(rest[0]);
167	    } else {
168	      const order = getLocaleDateOrder(resolveDateLocale(language)).filter(
169	        (field) => field !== "year",
170	      );
171	      rest.forEach((token, i) => {
172	        if (order[i] === "day") day = Number(token);
173	        else month = Number(token);
174	      });
175	    }
176	  }
177	
178	  const currentYear = new Date().getFullYear();
179	  if (year === null || year < 1 || year > currentYear) return invalid;
180	  if (month !== null && (month < 1 || month > 12)) return invalid;
181	  if (day !== null) {
182	    if (month === null) return invalid;
183	    const daysInMonth = new Date(year, month, 0).getDate();
184	    if (day < 1 || day > daysInMonth) return invalid;
185	  }
186	
187	  const pad = (n: number) => String(n).padStart(2, "0");
188	  if (day !== null && month !== null) {
189	    return { value: `${year}-${pad(month)}-${pad(day)}`, valid: true };
190	  }
191	  if (month !== null) return { value: `${year}-${pad(month)}`, valid: true };
192	  return { value: `${year}`, valid: true };
193	}
194	
195	export function formatDateWithFallback(
196	  dateString: DateInput,
197	  t: (key: string) => string,
198	  options?: FormatDateOptions,
199	): string {
200	  if (!dateString) return t("common.date-unknown");
201	  return formatDate(dateString, options) || t("common.date-unknown");
202	}
203	
204	export function formatDate(
205	  dateString: DateInput,
206	  options: FormatDateOptions = {},
207	): string {
208	  if (!dateString) return "";
209	  if (typeof dateString === "string") {
210	    const precision = getDatePrecision(dateString);
211	    const { language, ...intlOptions } = options;
212	    const locale = resolveDateLocale(language);
213	    if (precision === "year") {
214	      return dateString.slice(0, 4);
215	    }
216	    if (precision === "month") {
217	      const [year, month] = dateString.split("-").map(Number);
218	      const d = new Date(year, month - 1, 1);
219	      return new Intl.DateTimeFormat(locale, { year: "numeric", month: "long", ...intlOptions }).format(d);
220	    }
221	    if (precision === "day") {
222	      const [y, mo, day] = dateString.split("-").map(Number);
223	      const d = new Date(y, mo - 1, day);
224	      return new Intl.DateTimeFormat(locale, { day: "2-digit", month: "2-digit", year: "numeric", ...intlOptions }).format(d);
225	    }
226	    // Unrecognized string — fall through to Date parse for full ISO timestamps (event dates, etc.)
227	  }
228	  const date = parseDateInput(dateString);
229	  if (!date) return "";
230	  const { language, ...intlOptions } = options;
231	  return new Intl.DateTimeFormat(resolveDateLocale(language), {
232	    day: "2-digit",
233	    month: "2-digit",
234	    year: "numeric",
235	    ...intlOptions,
236	  }).format(date);
237	}
238	
239	export function formatDateTime(
240	  dateString: DateInput,
241	  options: FormatDateOptions = {},
242	): string {
243	  return formatDate(dateString, {
244	    hour: "2-digit",
245	    minute: "2-digit",
246	    second: "2-digit",
247	    ...options,
248	  });
249	}
250	
251	export function resolveDateLocale(language = i18n.resolvedLanguage): string {
252	  const fallbackLanguage = i18n.language?.split("-")[0];
253	  const baseLanguage = language?.split("-")[0] ?? fallbackLanguage;
254	  return LANGUAGE_LOCALES[baseLanguage] ?? LANGUAGE_LOCALES.en;
255	}
256	
257	function parseDateInput(dateInput: Date | string): Date | null {
258	  if (dateInput instanceof Date) {
259	    return Number.isNaN(dateInput.getTime()) ? null : dateInput;
260	  }
261	
262	  const dateOnlyParts = DATE_ONLY_RE.exec(dateInput);
263	  const date = dateOnlyParts
264	    ? new Date(
265	        Number(dateOnlyParts[1]),
266	        Number(dateOnlyParts[2]) - 1,
267	        Number(dateOnlyParts[3]),
268	      )
269	    : new Date(dateInput);
270	
271	  return Number.isNaN(date.getTime()) ? null : date;
272	}
