1	import { ReactNode, useState } from "react";
2	import { Button } from "@/components/ui/button";
3	import { ChevronDown, ChevronUp } from "lucide-react";
4	import { useTranslation } from "react-i18next";
5	
6	interface CollapsibleSectionProps {
7	  children: (collapsed: boolean) => ReactNode;
8	  totalCount: number;
9	  collapsedCount?: number;
10	}
11	
12	export const CollapsibleSection = ({
13	  children,
14	  totalCount,
15	  collapsedCount = 3,
16	}: CollapsibleSectionProps) => {
17	  const { t } = useTranslation(undefined, { keyPrefix: "sheet.member-sheet" });
18	  const [isExpanded, setIsExpanded] = useState(false);
19	  const shouldCollapse = totalCount > collapsedCount;
20	
21	  return (
22	    <div className="space-y-2">
23	      {children(!shouldCollapse || isExpanded)}
24	      {shouldCollapse && (
25	        <Button
26	          variant="ghost"
27	          size="sm"
28	          onClick={() => setIsExpanded(!isExpanded)}
29	          className="w-full"
30	        >
31	          {isExpanded ? (
32	            <>
33	              <ChevronUp />
34	              {t("show-less")}
35	            </>
36	          ) : (
37	            <>
38	              <ChevronDown />
39	              {t("show-more", { count: totalCount - collapsedCount })}
40	            </>
41	          )}
42	        </Button>
43	      )}
44	    </div>
45	  );
46	};
