24	}
25	
26	/**
27	 * Shared presentation for member-linked narrative content. It keeps the title,
28	 * date, place, details and actions in the same visual order whether the item
29	 * is shown in a member sheet or on the timeline.
30	 */
31	export function ContentCard({
32	  icon: Icon,
33	  title,
34	  date,
35	  location,
36	  description,
37	  metadata,
38	  actions,
39	  children,
40	  className,
41	  collapsible = false,
42	  expanded,
43	  onShowLocationOnMap,
44	}: ContentCardProps) {
45	  const [isExpanded, setIsExpanded] = useState(false);
46	  const hasDetails = Boolean(description);
47	  const canCollapse = collapsible && hasDetails;
48	  const showDetails = expanded ?? (canCollapse ? isExpanded : true);
49	
50	  const heading = (
51	    <>
52	      {canCollapse &&
53	        (showDetails ? (
54	          <ChevronDown className="h-4 w-4 shrink-0 text-muted-foreground" />
55	        ) : (
56	          <ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground" />
57	        ))}
58	      <Icon className="h-4 w-4 shrink-0 text-muted-foreground" />
59	      <span className="truncate font-medium">{title}</span>
60	      {metadata}
61	    </>
62	  );
63	
64	  return (
65	    <div
66	      className={cn(
67	        "rounded-lg border bg-card p-3 transition-colors hover:bg-accent/50",
68	        className,
69	      )}
70	    >
71	      <div className="flex items-start justify-between gap-2">
72	        <div className="min-w-0 flex-1">
73	          {canCollapse ? (
74	            <button
75	              type="button"
76	              aria-expanded={showDetails}
77	              onClick={() => setIsExpanded((value) => !value)}
78	              className="mb-1 flex w-full items-center gap-2 text-left"
79	            >
80	              {heading}
81	            </button>
82	          ) : (
83	            <div className="mb-1 flex items-center gap-2">{heading}</div>
84	          )}
85	
86	          {(date || location) && (
87	            <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-sm text-muted-foreground">
