import { create } from "zustand";
import { persist } from "zustand/middleware";

interface MemberSheetSectionsState {
  /**
   * Whether each Records-tab section (keyed by a stable section id, e.g.
   * "events") is collapsed. Missing entries default to expanded. Shared
   * between view and edit mode, and across members, since it reflects a
   * per-user layout preference rather than per-member data.
   */
  collapsedSections: Record<string, boolean>;
  toggleSection: (sectionId: string) => void;
}

export const useMemberSheetSectionsStore = create<MemberSheetSectionsState>()(
  persist(
    (set) => ({
      collapsedSections: {},
      toggleSection: (sectionId) =>
        set((state) => ({
          collapsedSections: {
            ...state.collapsedSections,
            [sectionId]: !state.collapsedSections[sectionId],
          },
        })),
    }),
    { name: "ft-member-sheet-sections", version: 1 },
  ),
);

import { ReactNode } from "react";
import { ChevronDown, ChevronRight } from "lucide-react";
import { Item, ItemContent, ItemTitle } from "@/components/ui/item";
import { useMemberSheetSectionsStore } from "@/hooks/useMemberSheetSectionsStore";

type Props = {
  /** Stable id shared between view and edit mode for the same section, e.g. "events". */
  sectionId: string;
  title: ReactNode;
  headerActions?: ReactNode;
  children: ReactNode;
};

/**
 * A Records-tab section card whose whole body (not just an inner list) can be
 * collapsed via its header. Collapse state is persisted per section id.
 */
export const CollapsibleSectionCard = ({
  sectionId,
  title,
  headerActions,
  children,
}: Props) => {
  const collapsed = useMemberSheetSectionsStore(
    (s) => s.collapsedSections[sectionId] ?? false,
  );
  const toggleSection = useMemberSheetSectionsStore((s) => s.toggleSection);

  return (
    <Item variant="muted">
      <ItemContent>
        <div className="flex items-center justify-between gap-2 mb-2">
          <button
            type="button"
            aria-expanded={!collapsed}
            onClick={() => toggleSection(sectionId)}
            className="flex min-w-0 items-center gap-1.5 text-left"
          >
            {collapsed ? (
              <ChevronRight className="w-4 h-4 shrink-0 text-muted-foreground" />
            ) : (
              <ChevronDown className="w-4 h-4 shrink-0 text-muted-foreground" />
            )}
            <ItemTitle className="truncate">{title}</ItemTitle>
          </button>
          {headerActions}
        </div>
        {!collapsed && children}
      </ItemContent>
    </Item>
  );
};

